/* Balance · pruebas de roles, ciclo de vida e ingreso por enlace y código. Ejecutar: node docs/requirements/balance/prototype/rules.test.js
   Esperado según INVENTARIO-BALANCE.md §12.3 (matriz D3), §12.7 (D7) y §12.3.5 (límite de intentos). */
const assert = require("node:assert/strict");
const R = require("./rules.js");
let ok = 0, bad = 0;
const t = (name, fn) => { try { fn(); ok++; console.log("OK   " + name); } catch (e) { bad++; console.log("FALLA " + name + "  -> " + e.message); } };
const mk = () => ({ id: "g1", closed: false, members: [{ id: "ana", role: "admin" }, { id: "beto", role: "member" }, { id: "carla", role: "member" }, { id: "diego", role: "admin" }], expenses: [{ id: "e1", payerId: "beto" }, { id: "e2", payerId: "ana" }], join: { token: "tok", code: "1234" } });
const as = (actorId, extra, g) => Object.assign({ session: true, hasAccess: true, group: g || mk(), actorId }, extra || {});
const allowed = (a, c) => R.can(a, c).allowed;

// ── Matriz D3 (administrador / miembro) ──
const MATRIX = [
  ["view", true, true], ["view_expenses", true, true], ["view_balances", true, true], ["view_settlement", true, true],
  ["add_expense", true, true], ["see_join", true, false], ["regenerate_join", true, false], ["manage_admins", true, false],
  ["edit_settings", true, false], ["change_currency", true, false], ["close_group", true, false], ["delete_group", true, false],
];
for (const [a, adm, mem] of MATRIX) t("Matriz D3 · " + a + ": administrador " + (adm ? "sí" : "no") + " · miembro " + (mem ? "sí" : "no"), () => {
  const g1 = mk(); g1.expenses = []; const extra = { targetId: "beto" };
  assert.equal(allowed(a, as("ana", extra, g1)), adm); assert.equal(allowed(a, as("carla", extra, g1)), mem);
  if (!mem && adm) { const r = R.can(a, as("carla", extra, g1)); assert.equal(r.status, 403); assert.ok(r.reason.length > 10 && r.who.length > 5, "debe explicar el porqué y a quién pedirlo"); }
});
t("Gastos · el miembro registra solo con él mismo como pagador; el administrador, con cualquiera", () => { assert.equal(allowed("add_expense", as("carla", { payerId: "carla" })), true); assert.equal(R.can("add_expense", as("carla", { payerId: "beto" })).status, 403); assert.equal(allowed("add_expense", as("ana", { payerId: "beto" })), true); });
t("Gastos · el miembro modifica y elimina solo los propios; el administrador cualquiera; cambiar el pagador es solo del administrador", () => { const own = { id: "e1", payerId: "beto" }, other = { id: "e2", payerId: "ana" }; for (const a of ["edit_expense", "delete_expense"]) { assert.equal(allowed(a, as("beto", { expense: own })), true); assert.equal(R.can(a, as("beto", { expense: other })).status, 403); assert.equal(allowed(a, as("ana", { expense: own })), true); } assert.equal(R.can("change_payer", as("beto", {})).status, 403); assert.equal(allowed("change_payer", as("ana", {})), true); });
// ── Pertenencia y sesión ──
t("Sin sesión → 401; sin acceso a Balance → 403; persona ajena al grupo → 404 en lectura y escritura", () => { assert.equal(R.can("view", { session: false, hasAccess: false }).status, 401); assert.equal(R.can("view", { session: true, hasAccess: false }).status, 403); for (const a of ["view", "view_expenses", "add_expense", "close_group", "see_join", "delete_group"]) assert.equal(R.can(a, as("intrusa")).status, 404, a); });
t("Cualquier persona con acceso puede crear grupos", () => { assert.equal(allowed("create_group", { session: true, hasAccess: true }), true); assert.equal(allowed("create_group", { session: true, hasAccess: false }), false); });
t("Acción desconocida: se deniega por defecto", () => { assert.equal(allowed("exportar_todo", as("ana")), false); });
// ── Ciclo de vida (D7) ──
t("Grupo cerrado: leer sí; cualquier escritura → 409 (también para el administrador, hasta reabrir)", () => { const g = mk(); g.closed = true; for (const a of ["view", "view_balances", "view_settlement"]) assert.equal(allowed(a, as("ana", {}, g)), true); for (const a of ["add_expense", "edit_settings", "change_currency", "regenerate_join"]) assert.equal(R.can(a, as("ana", { payerId: "ana" }, g)).status, 409, a); assert.equal(allowed("reopen_group", as("ana", {}, g)), true); assert.equal(R.can("reopen_group", as("carla", {}, g)).status, 403); });
t("Borrar el grupo: solo el administrador y solo si no tiene gastos (con gastos → 409)", () => { assert.equal(R.can("delete_group", as("ana")).status, 409); assert.equal(R.can("delete_group", as("ana")).code, "balance.group.has_expenses"); const g = mk(); g.expenses = []; assert.equal(allowed("delete_group", as("ana", {}, g)), true); assert.equal(R.can("delete_group", as("carla", {}, g)).status, 403); });
// ── Invariantes de administración ──
t("Último administrador: no se le puede quitar el cargo, quitar del grupo ni puede salir (409 balance.group.last_admin)", () => { const g = mk(); g.members = g.members.filter((m) => m.id !== "diego"); g.expenses = []; assert.equal(R.can("manage_admins", as("ana", { targetId: "ana" }, g)).code, "balance.group.last_admin"); assert.equal(R.can("remove_participant", as("ana", { targetId: "ana" }, g)).code, "balance.group.last_admin"); assert.equal(R.can("leave_group", as("ana", {}, g)).code, "balance.group.last_admin"); const g2 = mk(); g2.expenses = []; assert.equal(allowed("manage_admins", as("ana", { targetId: "diego" }, g2)), true); assert.equal(allowed("leave_group", as("ana", {}, g2)), true); });
t("Salir del grupo: sin gastos sí; con gastos → 409 balance.participant.has_expenses; quitar participantes igual criterio", () => { assert.equal(allowed("leave_group", as("carla")), true); assert.equal(R.can("leave_group", as("beto")).code, "balance.participant.has_expenses"); assert.equal(R.can("remove_participant", as("ana", { targetId: "beto" })).code, "balance.participant.has_expenses"); assert.equal(allowed("remove_participant", as("ana", { targetId: "carla" })), true); });
t("Un miembro nunca concede la administración (sin escalada)", () => { assert.equal(R.can("manage_admins", as("beto", { targetId: "beto" })).status, 403); });
// ── Ingreso por enlace y código ──
t("Ingreso: código correcto entra; enlace o código incorrectos dan el MISMO error genérico (no revela si el grupo existe)", () => { const guard = R.createJoinGuard(() => 0); const groups = [mk()]; assert.equal(guard.attempt({ accountId: "u", groups, token: "tok", code: "1234" }).ok, true); const a = guard.attempt({ accountId: "u2", groups, token: "tok", code: "0000" }), b = guard.attempt({ accountId: "u3", groups, token: "zzz", code: "1234" }), c = guard.attempt({ accountId: "u4", groups, token: "zzz", code: "0000" }); assert.deepEqual([a.status, a.code, a.message], [b.status, b.code, b.message]); assert.deepEqual([a.status, a.code, a.message], [c.status, c.code, c.message]); });
t("Ingreso: 5 fallos por cuenta y enlace → bloqueo de 15 min (429 con Retry-After); pasado el tiempo vuelve a permitirse; un ingreso correcto reinicia el contador", () => { let now = 0; const guard = R.createJoinGuard(() => now); const groups = [mk()]; const bad = () => guard.attempt({ accountId: "u", groups, token: "tok", code: "9999" }); for (let i = 0; i < 4; i++) assert.equal(bad().status, 400); assert.equal(guard.attempt({ accountId: "u", groups, token: "tok", code: "1234" }).ok, true); for (let i = 0; i < 5; i++) assert.equal(bad().status, 400); const lock = guard.attempt({ accountId: "u", groups, token: "tok", code: "1234" }); assert.equal(lock.status, 429); assert.equal(lock.retryAfterSec, 900); now = 899000; assert.equal(guard.attempt({ accountId: "u", groups, token: "tok", code: "1234" }).status, 429); now = 901000; assert.equal(guard.attempt({ accountId: "u", groups, token: "tok", code: "1234" }).ok, true); });
t("Ingreso: regenerar el enlace deja de servir el anterior", () => { const guard = R.createJoinGuard(() => 0); const g = mk(); assert.equal(guard.attempt({ accountId: "u", groups: [g], token: "tok", code: "1234" }).ok, true); g.join = { token: "nuevo", code: "4321" }; assert.equal(guard.attempt({ accountId: "u", groups: [g], token: "tok", code: "1234" }).status, 400); });
t("Token y código de demostración: 27 caracteres sin ambiguos y 4 dígitos con ceros a la izquierda", () => { assert.match(R.randomToken(), /^[abcdefghjkmnpqrstvwxyz23456789]{27}$/); assert.match(R.randomCode(() => 0.0007), /^0007$/); });
console.log("\n" + ok + " pruebas en verde, " + bad + " con fallas."); process.exit(bad ? 1 : 0);
